mapper.select:
SELECT e.*,
       st.name as student_name,
       c.name as course_name,
       t.name as teacher_name
FROM course_evaluation e
LEFT JOIN student st ON e.student_id = st.student_no
LEFT JOIN course_arrangement ca ON e.course_arrangement_id = ca.id
LEFT JOIN course c ON ca.course_code = c.id
LEFT JOIN teacher t ON e.teacher_no = t.teacher_no


        AND e.student_id = #{studentId}


        AND e.course_arrangement_id = #{courseArrangementId}


        AND e.teacher_no = #{teacherNo}


        AND e.status = #{status}


ORDER BY e.create_time DESC
LIMIT #{page}, #{size}

SELECT COUNT(*)
FROM course_evaluation e


        AND e.student_id = #{studentId}


        AND e.course_arrangement_id = #{courseArrangementId}


        AND e.teacher_no = #{teacherNo}


        AND e.status = #{status}

SELECT e.teacher_no as teacherNo, t.name as teacherName, COUNT(*) as evaluationCount, AVG(e.overall_score) as avgOverallScore, AVG(e.teaching_score) as avgTeachingScore, AVG(e.content_score) as avgContentScore, AVG(e.method_score) as avgMethodScore FROM course_evaluation e LEFT JOIN teacher t ON e.teacher_no = t.teacher_no LEFT JOIN course_arrangement ca ON e.course_arrangement_id = ca.id
e.teacher_no = #{teacherNo}
AND ca.semester = #{semester}
AND e.status = 'PUBLISHED' GROUP BY e.teacher_no, t.name
